type ID = string | number;
type Name = { firstName: string; lastName: string };
type Age = { age: number };
type Person = Name & Age;
type Status = 'active' | 'inactive' | 'pending';

function formatId(id: ID): string {
  return `ID: ${id}`;
}

function greet(person: Person): void {
  console.log(`Hello, ${person.firstName} ${person.lastName}!`);
  console.log(`Age: ${person.age}`);
}

function getStatusMessage(status: Status): string {
  switch (status) {
    case 'active': return 'User is active';
    case 'inactive': return 'User is inactive';
    case 'pending': return 'User is pending';
  }
}

console.log(formatId(123));
console.log(formatId('abc'));
greet({ firstName: 'Alice', lastName: 'Smith', age: 30 });
console.log(getStatusMessage('active'));

